def sub(id, title, pis, what, how, nums, real, traps, say, qs, learn=()):
    H[-1]['subs'].append(dict(id=id, title=title, pis=pis, what=what, how=how, nums=nums, real=real, traps=traps,
                              say=say, qs=[dict(q=q, a=a) for q, a in qs], learn=[list(x) for x in learn]))

IRS = ["IRS", "https://www.irs.gov"]; SSA = ["Social Security Administration", "https://www.ssa.gov"]
